-- modify "subscriptions" table
ALTER TABLE "subscriptions" ADD COLUMN "billing_authorization_id" character varying NOT NULL DEFAULT '', ADD COLUMN "billing_anchor_at" timestamptz NULL, ADD COLUMN "next_charge_at" timestamptz NULL, ADD COLUMN "dunning_attempts" bigint NOT NULL DEFAULT 0, ADD COLUMN "dunning_due_at" timestamptz NULL, ADD COLUMN "checkmark_included" boolean NOT NULL DEFAULT true, ADD COLUMN "credit_minor" bigint NOT NULL DEFAULT 0, ADD COLUMN "pending_plan_code" character varying NOT NULL DEFAULT '', ADD COLUMN "pending_interval" character varying NOT NULL DEFAULT '', ADD COLUMN "period_price_minor" bigint NOT NULL DEFAULT 0, ADD COLUMN "price_notice_amount_minor" bigint NOT NULL DEFAULT 0, ADD COLUMN "price_effective_at" timestamptz NULL, ADD COLUMN "card_expiry_month" bigint NOT NULL DEFAULT 0, ADD COLUMN "card_expiry_year" bigint NOT NULL DEFAULT 0, ADD COLUMN "card_expiry_noticed_at" timestamptz NULL, ADD COLUMN "ended_reason" character varying NOT NULL DEFAULT '';
-- create index "subscriptions_next_charge_due" to table: "subscriptions"
CREATE INDEX "subscriptions_next_charge_due" ON "subscriptions" ("next_charge_at") WHERE (next_charge_at IS NOT NULL);
-- create "subscription_periods" table
CREATE TABLE "subscription_periods" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "subscription_id" character varying NOT NULL, "kind" character varying NOT NULL, "plan_code" character varying NOT NULL, "interval" character varying NOT NULL, "period_starts_at" timestamptz NOT NULL, "period_ends_at" timestamptz NOT NULL, "line_items" jsonb NOT NULL, "period_price_minor" bigint NOT NULL DEFAULT 0, "subtotal_minor" bigint NOT NULL DEFAULT 0, "credit_applied_minor" bigint NOT NULL DEFAULT 0, "amount_due_minor" bigint NOT NULL DEFAULT 0, "currency" character varying NOT NULL, "checkmark_included" boolean NOT NULL DEFAULT true, "status" character varying NOT NULL DEFAULT 'open', "attempt_count" bigint NOT NULL DEFAULT 0, "idempotency_key" character varying NOT NULL, "payment_reference" character varying NOT NULL DEFAULT '', "failure_reason" character varying NOT NULL DEFAULT '', "paid_at" timestamptz NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "subscriptionperiod_idempotency_key" to table: "subscription_periods"
CREATE UNIQUE INDEX "subscriptionperiod_idempotency_key" ON "subscription_periods" ("idempotency_key");
-- create index "subscriptionperiod_payment_reference" to table: "subscription_periods"
CREATE INDEX "subscriptionperiod_payment_reference" ON "subscription_periods" ("payment_reference");
-- create index "subscriptionperiod_subscription_id_period_starts_at" to table: "subscription_periods"
CREATE INDEX "subscriptionperiod_subscription_id_period_starts_at" ON "subscription_periods" ("subscription_id", "period_starts_at");
